// BlockHost-Setup.exe: extracts the embedded BlockHost.zip to %LocalAppData%\BlockHost, installs the WebView2
// runtime if this PC lacks it, adds shortcuts and an "Apps & features" entry, then offers to launch.
// Assembly attributes and BuildInfo.Version come from a file generated by tools\build.ps1.
using System;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.IO.Compression;
using System.Net;
using System.Reflection;
using System.Text.RegularExpressions;
using System.Threading;
using System.Windows.Forms;
using Microsoft.Win32;

static class Setup
{
    static string Dest = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "BlockHost");
    const string Disclaimer = "NOT AN OFFICIAL MINECRAFT PRODUCT. NOT APPROVED BY OR ASSOCIATED WITH MOJANG OR MICROSOFT.";
    const string UninstallKey = "Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\BlockHost";

    [STAThread]
    static int Main()
    {
        Application.EnableVisualStyles();
        if (Running()) { MessageBox.Show("BlockHost is running. Click \"Quit BlockHost\" inside it, then run Setup again.", "BlockHost Setup", MessageBoxButtons.OK, MessageBoxIcon.Information); return 1; }
        if (MessageBox.Show("Install BlockHost " + BuildInfo.Version + " to:\n" + Dest + "\n\nYour servers and worlds stay in its data folder and are kept when you update.\n\n" + Disclaimer, "BlockHost Setup", MessageBoxButtons.OKCancel, MessageBoxIcon.Question) != DialogResult.OK) return 0;

        Exception error = null; string note = "";
        Form f = new Form();
        f.Text = "BlockHost Setup"; f.StartPosition = FormStartPosition.CenterScreen; f.FormBorderStyle = FormBorderStyle.FixedDialog; f.ControlBox = false; f.ClientSize = new Size(380, 80);
        Label l = new Label(); l.Text = "Installing BlockHost..."; l.AutoSize = true; l.Location = new Point(14, 14); f.Controls.Add(l);
        ProgressBar pb = new ProgressBar(); pb.Style = ProgressBarStyle.Marquee; pb.Location = new Point(14, 40); pb.Size = new Size(352, 20); f.Controls.Add(pb);
        Thread t = new Thread(delegate ()
        {
            try
            {
                Extract(); Shortcuts(); Register();
                if (!WebView2Installed()) { f.Invoke(new MethodInvoker(delegate { l.Text = "Installing the Microsoft WebView2 runtime..."; })); if (!InstallWebView2()) note = "\n\nThe Microsoft WebView2 runtime could not be installed, so BlockHost will open in your web browser instead."; }
            }
            catch (Exception e) { error = e; }
            f.Invoke(new MethodInvoker(f.Close));
        });
        f.Shown += delegate { t.Start(); };
        Application.Run(f);

        if (error != null) { MessageBox.Show("Install failed: " + error.Message, "BlockHost Setup", MessageBoxButtons.OK, MessageBoxIcon.Error); return 1; }
        if (MessageBox.Show("BlockHost is installed. A shortcut was added to your Desktop and Start menu. To remove it later, use Windows Settings > Apps." + note + "\n\nOpen it now?", "BlockHost Setup", MessageBoxButtons.YesNo, MessageBoxIcon.Information) == DialogResult.Yes)
            Process.Start(new ProcessStartInfo(Path.Combine(Dest, "BlockHost.exe")) { WorkingDirectory = Dest });
        return 0;
    }

    static void Extract()
    {
        Directory.CreateDirectory(Dest);
        string root = Path.GetFullPath(Dest) + Path.DirectorySeparatorChar;
        using (Stream s = Assembly.GetExecutingAssembly().GetManifestResourceStream("BlockHost.zip"))
        using (ZipArchive z = new ZipArchive(s, ZipArchiveMode.Read))
            foreach (ZipArchiveEntry e in z.Entries)
            {
                string p = Path.GetFullPath(Path.Combine(Dest, e.FullName));
                if (!p.StartsWith(root, StringComparison.OrdinalIgnoreCase)) continue; // refuse path escapes
                if (e.FullName.EndsWith("/")) { Directory.CreateDirectory(p); continue; }
                Directory.CreateDirectory(Path.GetDirectoryName(p));
                try { e.ExtractToFile(p, true); }
                catch (IOException) { if (!File.Exists(p)) throw; } // a locked, already-present file (e.g. node.exe) is fine
            }
    }

    static void Shortcuts()
    {
        string exe = Path.Combine(Dest, "BlockHost.exe");
        string[] places = { Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory), Environment.GetFolderPath(Environment.SpecialFolder.Programs) };
        Type sh = Type.GetTypeFromProgID("WScript.Shell");
        object shell = Activator.CreateInstance(sh);
        foreach (string dir in places)
        {
            object lnk = sh.InvokeMember("CreateShortcut", BindingFlags.InvokeMethod, null, shell, new object[] { Path.Combine(dir, "BlockHost.lnk") });
            Type lt = lnk.GetType();
            lt.InvokeMember("TargetPath", BindingFlags.SetProperty, null, lnk, new object[] { exe });
            lt.InvokeMember("WorkingDirectory", BindingFlags.SetProperty, null, lnk, new object[] { Dest });
            lt.InvokeMember("Description", BindingFlags.SetProperty, null, lnk, new object[] { "Minecraft server manager" });
            lt.InvokeMember("Save", BindingFlags.InvokeMethod, null, lnk, null);
        }
    }

    // Per-user "Apps & features" entry, so BlockHost can be removed like any other app.
    static void Register()
    {
        using (RegistryKey k = Registry.CurrentUser.CreateSubKey(UninstallKey))
        {
            k.SetValue("DisplayName", "BlockHost");
            k.SetValue("DisplayVersion", BuildInfo.Version);
            k.SetValue("Publisher", "BlockHost");
            k.SetValue("InstallLocation", Dest);
            k.SetValue("DisplayIcon", Path.Combine(Dest, "BlockHost.exe"));
            k.SetValue("UninstallString", "\"" + Path.Combine(Dest, "Uninstall.exe") + "\"");
            k.SetValue("NoModify", 1, RegistryValueKind.DWord);
            k.SetValue("NoRepair", 1, RegistryValueKind.DWord);
            long kb = 0; try { foreach (string fl in Directory.GetFiles(Dest, "*", SearchOption.AllDirectories)) if (fl.IndexOf("\\data\\", StringComparison.OrdinalIgnoreCase) < 0) kb += new FileInfo(fl).Length / 1024; } catch { }
            k.SetValue("EstimatedSize", (int)Math.Min(int.MaxValue, kb), RegistryValueKind.DWord);
        }
    }

    const string WvGuid = "{F3017226-FE2A-4295-8BDF-00C3A9A7E4C5}";
    static bool WebView2Installed()
    {
        string[] keys = {
            "HKEY_LOCAL_MACHINE\\SOFTWARE\\WOW6432Node\\Microsoft\\EdgeUpdate\\Clients\\" + WvGuid,
            "HKEY_LOCAL_MACHINE\\SOFTWARE\\Microsoft\\EdgeUpdate\\Clients\\" + WvGuid,
            "HKEY_CURRENT_USER\\Software\\Microsoft\\EdgeUpdate\\Clients\\" + WvGuid
        };
        foreach (string k in keys) { try { string pv = Registry.GetValue(k, "pv", null) as string; if (!string.IsNullOrEmpty(pv) && pv != "0.0.0.0") return true; } catch { } }
        return false;
    }

    // Runs Microsoft's signed Evergreen Bootstrapper (embedded in this Setup) silently.
    static bool InstallWebView2()
    {
        try
        {
            string tmp = Path.Combine(Path.GetTempPath(), "BlockHost-WebView2Setup.exe");
            using (Stream s = Assembly.GetExecutingAssembly().GetManifestResourceStream("WebView2Setup.exe"))
            using (FileStream o = File.Create(tmp)) s.CopyTo(o);
            using (Process p = Process.Start(new ProcessStartInfo(tmp, "/silent /install") { UseShellExecute = false, CreateNoWindow = true })) p.WaitForExit(10 * 60 * 1000);
            try { File.Delete(tmp); } catch { }
            return WebView2Installed();
        }
        catch { return false; }
    }

    static bool Running()
    {
        try
        {
            string f = Path.Combine(Dest, "data\\instance.json");
            if (!File.Exists(f)) return false;
            Match m = Regex.Match(File.ReadAllText(f), "\"port\"\\s*:\\s*(\\d+)");
            if (!m.Success) return false;
            HttpWebRequest req = (HttpWebRequest)WebRequest.Create("http://127.0.0.1:" + m.Groups[1].Value + "/api/ping");
            req.Timeout = 1500;
            using (StreamReader r = new StreamReader(req.GetResponse().GetResponseStream())) { string t = r.ReadToEnd(); return t.Contains("\"blockhost\"") || t.Contains("\"mcsm\""); }
        }
        catch { return false; }
    }
}
